    exp=[{'id':c['id'],'essentialUnderstandingDe':c['understandingFocusDe'],'essentialUnderstandingEn':c['understandingFocusEn'],'observablePerformanceDe':c['expectedPerformanceDe'],'observablePerformanceEn':c['expectedPerformanceEn']} for c in cs]
